#!/usr/bin/env bash
# Client smoke test (CI): starts the real Minecraft client with the mod under a virtual display
# (software OpenGL), loads the world generated by tools/smoke_server.sh and lets the mod's
# ClientSmokeTest (-Drunecraft.clientSmoke=true, ModDevGradle run "clientSmoke") walk through Gielinor taking
# screenshots, then runs the in-game self-test as the real player ("/rc selftest real <filter>", filter
# $CLIENT_SELFTEST, default "minigame:,raid:,boss:" plus the skill and item-making spell checks; "none" skips it;
# its SELFTEST lines are printed but don't fail this script). Then scans the rest of the log for crashes, model/texture problems and RuneCraft
# errors and writes a report to $GITHUB_STEP_SUMMARY (when set). Exits non-zero on any problem.
#
# Needs: xvfb-run and Mesa (sudo apt-get install -y xvfb mesa-utils libgl1-mesa-dri), and
# build/smoke/world from a previous tools/smoke_server.sh run.
set -uo pipefail
cd "$(dirname "$0")/.."
R=build/clientsmoke
SUMMARY=${GITHUB_STEP_SUMMARY:-/dev/null}
if [ ! -f build/smoke/world/level.dat ]; then
    echo "FAIL: build/smoke/world is missing - run tools/smoke_server.sh first"
    echo "### Client smoke test: not run (no server world)" >> "$SUMMARY"
    exit 1
fi
rm -rf "$R/saves" "$R/screenshots" "$R/logs" "$R/crash-reports" "$R/quit_stuck.txt"
mkdir -p "$R/saves"
cp -r build/smoke/world "$R/saves/smoke"
rm -f "$R/saves/smoke/session.lock"
# Drop the server run's force-loaded chunk lists so the client world starts light.
find "$R/saves/smoke" -name chunks.dat -delete
cat > "$R/options.txt" <<'EOF'
version:3955
onboardAccessibility:false
renderDistance:6
simulationDistance:6
pauseOnLostFocus:false
narrator:0
tutorialStep:none
skipMultiplayerWarning:true
joinedFirstServer:true
soundCategory_master:0.0
graphicsMode:0
maxFps:60
enableVsync:false
fullscreen:false
guiScale:2
lang:en_us
EOF

export LIBGL_ALWAYS_SOFTWARE=1
echo "---- starting client (timeout ${CLIENT_TIMEOUT:-1500}s) ----"
# Passed to the client JVM through the ModDevGradle run config (see build.gradle, clientSmoke).
export RUNECRAFT_CLIENT_SELFTEST="${CLIENT_SELFTEST:-minigame:,raid:,boss:,slayer:,quest:steps:,quest:walk:,skill:,enchant_,telekinetic,bake_pie,superglass,string_jewellery,plank_make,hud:}"
export RUNECRAFT_CLIENT_SELFTEST_MINUTES="${CLIENT_SELFTEST_MINUTES:-14}"
timeout "${CLIENT_TIMEOUT:-1500}" xvfb-run -a -s "-screen 0 1280x720x24" \
    ./gradlew runClientSmoke --no-daemon --stacktrace > "$R/run.log" 2>&1
code=$?
LOG="$R/logs/latest.log"
[ -f "$LOG" ] || LOG="$R/run.log"
echo "client exited with code $code; log: $LOG"
grep -n 'ClientSmoke\|RUNECRAFT CLIENT SMOKE' "$LOG" | tail -150

# The real-player self-test block (between SELFTEST BEGIN and END) is reported on its own and kept out of the
# strict error checks below, like tools/smoke_server.sh does: its failures are findings, not client problems.
FULL_LOG="$LOG"
awk '/SELFTEST BEGIN/ { on = 1 } on { print } /SELFTEST END/ { on = 0 }' "$FULL_LOG" > "$R/selftest.log"
awk '/SELFTEST BEGIN/ { skip = 1 } !skip { print } /SELFTEST END/ { skip = 0 }' "$FULL_LOG" > "$R/strict.log"
LOG="$R/strict.log"
echo "---- real-player self-test (/rc selftest real) ----"
if grep -q 'SELFTEST END' "$R/selftest.log"; then
    grep -v 'SELFTEST-SUMMARY\|SELFTEST END' "$R/selftest.log" | grep -o 'SELFTEST .*'
    echo "---- real-player self-test: errors and warnings logged during it ----"
    grep -A6 '/ERROR\]' "$R/selftest.log" | grep -v 'SELFTEST' | head -150
    grep '/WARN\]' "$R/selftest.log" | sed 's/^\[[^]]*\] //' | sort | uniq -c | sort -rn | head -40
    echo "---- real-player self-test summary ----"
    grep -o 'SELFTEST [0-9]* passed, [0-9]* failed.*' "$R/selftest.log" | tail -1
    grep -o 'SELFTEST-SUMMARY .*' "$R/selftest.log" | sed 's/^SELFTEST-SUMMARY //'
    selftest_line="$(grep -o 'SELFTEST [0-9]* passed, [0-9]* failed.*' "$R/selftest.log" | tail -1)"
elif grep -q 'SELFTEST BEGIN' "$R/selftest.log"; then
    grep -o 'SELFTEST .*' "$R/selftest.log"
    echo "WARN: the real-player self-test did not finish"
    echo "SELFTEST $(grep -c 'SELFTEST PASS' "$R/selftest.log") passed, $(grep -c 'SELFTEST FAIL' "$R/selftest.log") failed (unfinished)"
    selftest_line="unfinished"
else
    echo "WARN: the real-player self-test never started"
    selftest_line="not run"
fi

problems=()
ok=0
grep -q 'RUNECRAFT CLIENT SMOKE: OK' "$FULL_LOG" && ok=1
grep -q 'RUNECRAFT CLIENT SMOKE: FAILED' "$FULL_LOG" && problems+=("walkthrough reported errors")
[ "$code" = 124 ] && problems+=("timed out")
[ "$code" != 0 ] && [ "$code" != 124 ] && problems+=("exit code $code")
[ $ok = 1 ] || problems+=("no 'RUNECRAFT CLIENT SMOKE: OK' line")
ls "$R"/crash-reports/*.txt >/dev/null 2>&1 && problems+=("crash report written")
# ClientSmokeTest's watchdog writes every thread's stack when quitting the world hangs.
if [ -f "$R/quit_stuck.txt" ]; then
    problems+=("quitting hung (thread dump below)")
    echo "---- quit watchdog thread dump ----"
    head -400 "$R/quit_stuck.txt"
fi
grep -q 'Game crashed\|---- Minecraft Crash Report ----\|Crash report saved' "$R/run.log" "$FULL_LOG" && problems+=("game crashed")

ASSET_RE='Unable to load model|Missing textures|Exception loading|Failed to load|Unable to resolve texture|Using missing texture|Unable to parse'
grep -E "$ASSET_RE" "$LOG" > "$R/asset_problems.txt"
grep -i 'runecraft' "$R/asset_problems.txt" > "$R/asset_problems_runecraft.txt"
n_assets=$(grep -c . "$R/asset_problems_runecraft.txt")
[ "$n_assets" -gt 0 ] && problems+=("$n_assets RuneCraft model/texture problem line(s)")
grep -E '/ERROR\]' "$LOG" | grep -i 'runecraft' > "$R/runecraft_errors.txt"
n_err=$(grep -c . "$R/runecraft_errors.txt")
[ "$n_err" -gt 0 ] && problems+=("$n_err RuneCraft ERROR line(s)")
n_trace=$(grep -cE '^\s*at ([^ ]*/)?com\.runecraft\.' "$LOG")
[ "$n_trace" -gt 0 ] && problems+=("exceptions through RuneCraft code ($n_trace stack frames)")

shots=$(ls "$R"/screenshots/*.png 2>/dev/null | wc -l)
{
    if [ ${#problems[@]} = 0 ]; then
        echo "### Client smoke test: OK"
    else
        echo "### Client smoke test: FAILED"
        for p in "${problems[@]}"; do echo "- $p"; done
    fi
    echo
    echo "Exit code: $code. Screenshots: $shots (artifact **client-smoke**)."
    echo
    echo "Real-player self-test: $selftest_line"
    echo
    if [ "$shots" -gt 0 ]; then
        echo "<details><summary>Screenshots</summary>"
        echo
        for f in "$R"/screenshots/*.png; do echo "- $(basename "$f")"; done
        echo
        echo "</details>"
    fi
    for f in asset_problems_runecraft runecraft_errors; do
        if [ -s "$R/$f.txt" ]; then
            echo
            echo "<details><summary>$f ($(grep -c . "$R/$f.txt") lines)</summary>"
            echo
            echo '```'
            head -40 "$R/$f.txt"
            echo '```'
            echo "</details>"
        fi
    done
    if [ -s "$R/asset_problems.txt" ]; then
        echo
        echo "<details><summary>All model/texture load warnings ($(grep -c . "$R/asset_problems.txt") lines)</summary>"
        echo
        echo '```'
        head -40 "$R/asset_problems.txt"
        echo '```'
        echo "</details>"
    fi
    echo
    echo "<details><summary>Walkthrough log</summary>"
    echo
    echo '```'
    grep 'ClientSmoke\|RUNECRAFT CLIENT SMOKE' "$LOG" | tail -80
    echo '```'
    echo "</details>"
} >> "$SUMMARY"

if [ ${#problems[@]} = 0 ]; then
    echo "Client smoke test passed ($shots screenshots)"
    exit 0
fi
echo "FAIL: client smoke test:"
printf '  - %s\n' "${problems[@]}"
echo "---- RuneCraft model/texture problems ----"; head -40 "$R/asset_problems_runecraft.txt"
echo "---- RuneCraft errors ----"; head -40 "$R/runecraft_errors.txt"
echo "---- end of run log ----"; tail -60 "$R/run.log"
exit 1
